-- ============================================================================
-- seed_kenya_questions_batch3.sql
-- 64 NEW local-flavour questions (matatus, Safaricom and tech, athletes, Swahili
-- and Sheng, food and culture, history, wildlife, music) with a "Did you know?"
-- line each. Run AFTER 024_content_quality.sql (needs the did_you_know column).
-- Safe to re-run: rows whose question text already exists are skipped.
-- Please have a Kenyan reviewer skim the facts before release.
-- ============================================================================

insert into public.categories (name)
select c.name from (values ($q$Kenyan Food & Culture$q$), ($q$Kenyan Geography$q$), ($q$Kenyan History$q$), ($q$Kenyan Sports$q$), ($q$Kenyan Wildlife & Culture$q$), ($q$Matatus & Transport$q$), ($q$Music & Entertainment$q$), ($q$Safaricom & Tech$q$), ($q$Swahili & Sheng$q$)) as c(name)
where not exists (select 1 from public.categories x where x.name = c.name);

insert into public.questions
  (category_id, question_text, option_a, option_b, option_c, option_d, correct_option, difficulty, did_you_know)
select (select id from public.categories where name = v.cat limit 1),
       v.question_text, v.a, v.b, v.c, v.d, v.correct, v.difficulty, v.fact
from (values
  ($q$Matatus & Transport$q$, $q$What is the name of the standard gauge railway line that links Mombasa and Nairobi?$q$, $q$Madaraka Express$q$, $q$Lunatic Express$q$, $q$Uhuru Express$q$, $q$Jubilee Line$q$, 'a', 'easy', $q$The Madaraka Express began passenger service on 31 May 2017, which was Madaraka Day.$q$),
  ($q$Matatus & Transport$q$, $q$The old Uganda Railway built by the British was nicknamed the...$q$, $q$Lunatic Express$q$, $q$Madaraka Express$q$, $q$Tsavo Special$q$, $q$Safari Express$q$, 'a', 'medium', $q$The line was nicknamed the "Lunatic Express" because of its huge cost and the dangers of building it. It reached Kisumu in 1901.$q$),
  ($q$Matatus & Transport$q$, $q$What is the name of Kenya's busiest international airport?$q$, $q$Wilson Airport$q$, $q$Kisumu International Airport$q$, $q$Jomo Kenyatta International Airport$q$, $q$Moi International Airport$q$, 'c', 'easy', $q$JKIA is named after Kenya's first President. Wilson Airport, also in Nairobi, mostly handles small and charter flights.$q$),
  ($q$Matatus & Transport$q$, $q$Which Nairobi airport mostly handles small domestic and charter flights?$q$, $q$Jomo Kenyatta International Airport$q$, $q$Wilson Airport$q$, $q$Eastleigh Airport$q$, $q$Embakasi Airport$q$, 'b', 'medium', $q$Wilson Airport is one of the busiest small-aircraft airports in Africa.$q$),
  ($q$Matatus & Transport$q$, $q$In matatu slang, what is the fare collector commonly called?$q$, $q$Dereva$q$, $q$Fundi$q$, $q$Makanga$q$, $q$Mzee$q$, 'c', 'easy', $q$The makanga collects fares and calls out the route. The dereva is the driver.$q$),
  ($q$Matatus & Transport$q$, $q$The name "boda boda" is said to come from which phrase?$q$, $q$Both on board$q$, $q$Bike on road$q$, $q$Border to border$q$, $q$Body to body$q$, 'c', 'medium', $q$Bicycle taxis first ferried people across the Kenya–Uganda border, shouting "border, border".$q$),
  ($q$Matatus & Transport$q$, $q$Kenya Airways is nicknamed...$q$, $q$The Wings of Kenya$q$, $q$The Savanna Flyer$q$, $q$The Eagle of the East$q$, $q$The Pride of Africa$q$, 'd', 'medium', $q$Kenya Airways flies from its hub at Jomo Kenyatta International Airport in Nairobi.$q$),
  ($q$Matatus & Transport$q$, $q$The Nairobi terminus of the Standard Gauge Railway is located in which area?$q$, $q$Kasarani$q$, $q$Ruaraka$q$, $q$Westlands$q$, $q$Syokimau$q$, 'd', 'hard', $q$The Nairobi SGR terminus sits at Syokimau, close to JKIA and the Mombasa Road.$q$),
  ($q$Matatus & Transport$q$, $q$The Nairobi Expressway, opened in 2022, is what kind of road?$q$, $q$A tunnel under the city$q$, $q$A railway bridge$q$, $q$An elevated toll road$q$, $q$A free dual carriageway$q$, 'c', 'medium', $q$It runs above existing roads, easing traffic between Mlolongo and Westlands.$q$),
  ($q$Safaricom & Tech$q$, $q$Which mobile money service was launched in Kenya in 2007?$q$, $q$T-Kash$q$, $q$M-Pesa$q$, $q$M-Shwari$q$, $q$Airtel Money$q$, 'b', 'easy', $q$The "M" stands for mobile and "pesa" is Swahili for money. M-Pesa is now used far beyond Kenya.$q$),
  ($q$Safaricom & Tech$q$, $q$What does the Swahili word "pesa" mean?$q$, $q$Money$q$, $q$Phone$q$, $q$Pay later$q$, $q$Send$q$, 'a', 'easy', $q$M-Pesa literally means "mobile money".$q$),
  ($q$Safaricom & Tech$q$, $q$Safaricom's headquarters are in which Nairobi area?$q$, $q$Embakasi$q$, $q$Westlands$q$, $q$Kilimani$q$, $q$Karen$q$, 'b', 'medium', $q$Safaricom House stands on Waiyaki Way in Westlands.$q$),
  ($q$Safaricom & Tech$q$, $q$Which Kenyan-born platform mapped reports of violence after the 2007–08 election?$q$, $q$Ushahidi$q$, $q$M-Farm$q$, $q$Twiga$q$, $q$Sendy$q$, 'a', 'medium', $q$"Ushahidi" is Swahili for "testimony". The software has since been used around the world.$q$),
  ($q$Safaricom & Tech$q$, $q$Konza Technopolis, planned as a Kenyan tech city, is in which county?$q$, $q$Nakuru$q$, $q$Kiambu$q$, $q$Machakos$q$, $q$Kajiado$q$, 'c', 'hard', $q$Konza lies along the Nairobi–Mombasa highway and is part of the "Silicon Savannah" vision.$q$),
  ($q$Safaricom & Tech$q$, $q$What nickname is given to Kenya's technology scene?$q$, $q$Tech Mara$q$, $q$Digital Rift$q$, $q$Silicon Valley East$q$, $q$Silicon Savannah$q$, 'd', 'easy', $q$Nairobi is a hub for mobile payments and start-ups.$q$),
  ($q$Safaricom & Tech$q$, $q$What is Kenya's international dialling code?$q$, $q$+254$q$, $q$+255$q$, $q$+256$q$, $q$+250$q$, 'a', 'easy', $q$Tanzania is +255, Uganda +256 and Rwanda +250.$q$),
  ($q$Safaricom & Tech$q$, $q$Which two numbers can you call for emergencies in Kenya?$q$, $q$100 and 101$q$, $q$911 and 112$q$, $q$999 and 112$q$, $q$777 and 999$q$, 'c', 'medium', $q$Both 999 and 112 connect you to emergency services.$q$),
  ($q$Safaricom & Tech$q$, $q$M-Pesa's "Fuliza" service lets you...$q$, $q$Save for school fees$q$, $q$Buy airtime for free$q$, $q$Send money abroad$q$, $q$Complete a payment with an overdraft$q$, 'd', 'medium', $q$"Fuliza" is Swahili for "keep going" or "carry on". It was launched in 2019.$q$),
  ($q$Kenyan Sports$q$, $q$In which city did Eliud Kipchoge run the first sub-two-hour marathon in 2019?$q$, $q$Chicago$q$, $q$Vienna$q$, $q$London$q$, $q$Berlin$q$, 'b', 'medium', $q$He ran 1:59:40 in the INEOS 1:59 Challenge. It does not count as an official record because pacers were rotated.$q$),
  ($q$Kenyan Sports$q$, $q$Who set the marathon world record of 2:00:35 in Chicago in 2023?$q$, $q$Evans Chebet$q$, $q$Geoffrey Kamworor$q$, $q$Kelvin Kiptum$q$, $q$Eliud Kipchoge$q$, 'c', 'hard', $q$Kelvin Kiptum died in a road accident in February 2024, aged 24.$q$),
  ($q$Kenyan Sports$q$, $q$At which Olympics did David Rudisha set his 800m world record?$q$, $q$London 2012$q$, $q$Sydney 2000$q$, $q$Rio 2016$q$, $q$Beijing 2008$q$, 'a', 'medium', $q$He led from the front and ran 1:40.91.$q$),
  ($q$Kenyan Sports$q$, $q$How many Olympic 1500m gold medals in a row had Faith Kipyegon won by the end of the Paris 2024 Games?$q$, $q$Four$q$, $q$One$q$, $q$Two$q$, $q$Three$q$, 'd', 'hard', $q$She won in Rio 2016, Tokyo 2020 and Paris 2024.$q$),
  ($q$Kenyan Sports$q$, $q$Which Kenyan town is home to the WRC Safari Rally base and Hell's Gate nearby?$q$, $q$Kitale$q$, $q$Voi$q$, $q$Nanyuki$q$, $q$Naivasha$q$, 'd', 'medium', $q$The Safari Rally returned to the World Rally Championship in 2021.$q$),
  ($q$Kenyan Sports$q$, $q$What is the nickname of Kenya's national rugby sevens team?$q$, $q$Simbas$q$, $q$Chuis$q$, $q$Morans$q$, $q$Shujaa$q$, 'd', 'easy', $q$"Shujaa" is Swahili for hero or warrior. The women's side are the Lionesses.$q$),
  ($q$Kenyan Sports$q$, $q$What is the nickname of Kenya's national football team?$q$, $q$Super Eagles$q$, $q$Black Stars$q$, $q$Indomitable Lions$q$, $q$Harambee Stars$q$, 'd', 'easy', $q$"Harambee" means "let us pull together".$q$),
  ($q$Kenyan Sports$q$, $q$In which year did Kipchoge Keino win Olympic 1500m gold?$q$, $q$1972$q$, $q$1968$q$, $q$1964$q$, $q$1960$q$, 'b', 'medium', $q$He won in Mexico City in 1968, then won the 3000m steeplechase in 1972.$q$),
  ($q$Kenyan Sports$q$, $q$Which Kenyan town in Elgeyo-Marakwet is called the "Home of Champions"?$q$, $q$Iten$q$, $q$Kericho$q$, $q$Nyahururu$q$, $q$Eldoret$q$, 'a', 'medium', $q$Iten sits at roughly 2,400 metres above sea level, popular for high-altitude training.$q$),
  ($q$Swahili & Sheng$q$, $q$What does the proverb "Haraka haraka haina baraka" mean?$q$, $q$Hurry hurry has no blessing$q$, $q$Unity is strength$q$, $q$Slow and steady wins$q$, $q$Hard work pays$q$, 'a', 'easy', $q$In other words: haste makes waste.$q$),
  ($q$Swahili & Sheng$q$, $q$What does "Harambee" mean?$q$, $q$Long live Kenya$q$, $q$Let us all pull together$q$, $q$Welcome home$q$, $q$Peace and love$q$, 'b', 'easy', $q$Harambee appears on the Kenyan coat of arms and is used for community fundraising.$q$),
  ($q$Swahili & Sheng$q$, $q$What does "Pole pole ndio mwendo" mean?$q$, $q$Walk with friends$q$, $q$The road is long$q$, $q$Speed is life$q$, $q$Slowly slowly is the way to go$q$, 'd', 'medium', $q$Pole pole is also a common way to say "take it easy".$q$),
  ($q$Swahili & Sheng$q$, $q$What does "Umoja ni nguvu" mean?$q$, $q$Time is gold$q$, $q$Money is power$q$, $q$Unity is strength$q$, $q$Peace is life$q$, 'c', 'easy', $q$"Umoja" is unity and "nguvu" is strength.$q$),
  ($q$Swahili & Sheng$q$, $q$What does "Kidole kimoja hakivunji chawa" mean?$q$, $q$Do not point at others$q$, $q$One finger cannot crush a louse$q$, $q$A small step is a step$q$, $q$Count your blessings$q$, 'b', 'medium', $q$It teaches that big tasks need teamwork.$q$),
  ($q$Swahili & Sheng$q$, $q$Complete the meaning: "Asiyefunzwa na mamaye hufunzwa na ulimwengu".$q$, $q$A mother always knows best$q$, $q$The world is a school for kings$q$, $q$Learn early, rest later$q$, $q$Who is not taught by their mother is taught by the world$q$, 'd', 'hard', $q$It stresses that lessons you skip at home, life will teach you, often harder.$q$),
  ($q$Swahili & Sheng$q$, $q$What does "Maji ukiyavulia nguo, huna budi kuyaoga" teach?$q$, $q$Once you start something, finish it$q$, $q$Water is life$q$, $q$Never swim in rivers$q$, $q$Clean clothes bring luck$q$, 'a', 'hard', $q$Literally: if you take your clothes off for the water, you must bathe.$q$),
  ($q$Swahili & Sheng$q$, $q$In Sheng, what is a "mathree"?$q$, $q$A football$q$, $q$A friend$q$, $q$A matatu$q$, $q$A mobile phone$q$, 'c', 'medium', $q$Sheng mixes Swahili, English and other Kenyan languages and keeps changing.$q$),
  ($q$Swahili & Sheng$q$, $q$In Sheng, what does "mbogi" usually mean?$q$, $q$A song$q$, $q$A kind of food$q$, $q$A group of friends$q$, $q$A shop$q$, 'c', 'hard', $q$You might hear "mbogi yangu" for "my squad".$q$),
  ($q$Swahili & Sheng$q$, $q$What number is "nane" in Swahili?$q$, $q$7$q$, $q$9$q$, $q$8$q$, $q$6$q$, 'c', 'easy', $q$Saba is 7, nane is 8 and tisa is 9.$q$),
  ($q$Swahili & Sheng$q$, $q$What is "Asante sana" in English?$q$, $q$You are welcome$q$, $q$Good morning$q$, $q$Thank you very much$q$, $q$See you later$q$, 'c', 'easy', $q$"Karibu" is the reply: you are welcome.$q$),
  ($q$Kenyan Food & Culture$q$, $q$Ugali is traditionally made from...$q$, $q$Rice flour$q$, $q$Banana$q$, $q$Cassava leaves$q$, $q$Maize flour$q$, 'd', 'easy', $q$Ugali is usually eaten with sukuma wiki, meat or fish.$q$),
  ($q$Kenyan Food & Culture$q$, $q$What does "nyama choma" mean?$q$, $q$Stewed beans$q$, $q$Fried fish$q$, $q$Smoked sausage$q$, $q$Roast meat$q$, 'd', 'easy', $q$It is often goat or beef grilled over charcoal and shared with friends.$q$),
  ($q$Kenyan Food & Culture$q$, $q$"Sukuma wiki" literally means...$q$, $q$Sunday lunch$q$, $q$Push the week$q$, $q$Market day$q$, $q$Green vegetable$q$, 'b', 'medium', $q$The cheap greens help families stretch the budget until the end of the week.$q$),
  ($q$Kenyan Food & Culture$q$, $q$Mursik, a fermented milk drink, is traditional among which community?$q$, $q$Luhya$q$, $q$Kalenjin$q$, $q$Kamba$q$, $q$Luo$q$, 'b', 'medium', $q$It is served in a gourd smoked with special wood, which gives it a distinct taste.$q$),
  ($q$Kenyan Food & Culture$q$, $q$Githeri is a dish made from...$q$, $q$Rice and peas$q$, $q$Potatoes and spinach$q$, $q$Maize and beans$q$, $q$Millet and fish$q$, 'c', 'easy', $q$It is a staple, often cooked in big pots for schools and gatherings.$q$),
  ($q$Kenyan Food & Culture$q$, $q$Which cuisine influenced the Kenyan chapati?$q$, $q$Portuguese$q$, $q$Chinese$q$, $q$Indian$q$, $q$Ethiopian$q$, 'c', 'medium', $q$Indian traders and railway workers helped bring flatbreads to East Africa.$q$),
  ($q$Kenyan Food & Culture$q$, $q$Which Kenyan highland town is famous for its tea estates?$q$, $q$Lodwar$q$, $q$Garissa$q$, $q$Kericho$q$, $q$Malindi$q$, 'c', 'medium', $q$Kenya is one of the world's largest exporters of black tea.$q$),
  ($q$Kenyan Food & Culture$q$, $q$The Maasai are famous for a jumping dance called...$q$, $q$Isukuti$q$, $q$Mwanzele$q$, $q$Adumu$q$, $q$Chakacha$q$, 'c', 'easy', $q$Warriors compete to jump the highest while staying straight.$q$),
  ($q$Kenyan Food & Culture$q$, $q$Which old town on the Kenyan coast is a UNESCO World Heritage Site known for Swahili architecture?$q$, $q$Kisii$q$, $q$Lamu$q$, $q$Embu$q$, $q$Kitale$q$, 'b', 'medium', $q$Lamu Old Town is widely described as the oldest continuously inhabited Swahili settlement in East Africa.$q$),
  ($q$Kenyan History$q$, $q$In which year did the Mau Mau uprising begin, leading to a state of emergency?$q$, $q$1957$q$, $q$1948$q$, $q$1952$q$, $q$1963$q$, 'c', 'medium', $q$The state of emergency was declared in October 1952.$q$),
  ($q$Kenyan History$q$, $q$In which year did Kenya become a republic?$q$, $q$1964$q$, $q$1969$q$, $q$1960$q$, $q$1963$q$, 'a', 'medium', $q$Jamhuri Day is celebrated every 12 December.$q$),
  ($q$Kenyan History$q$, $q$What is celebrated on Madaraka Day?$q$, $q$The new constitution$q$, $q$Independence from Britain$q$, $q$Internal self-government in 1963$q$, $q$The first elections in 1992$q$, 'c', 'medium', $q$Madaraka Day is on 1 June. Madaraka means "authority" or "self-rule".$q$),
  ($q$Kenyan History$q$, $q$Mashujaa Day, 20 October, was formerly known as...$q$, $q$Kenyatta Day$q$, $q$Uhuru Day$q$, $q$Moi Day$q$, $q$Jamhuri Day$q$, 'a', 'medium', $q$The 2010 Constitution renamed it Mashujaa (Heroes) Day.$q$),
  ($q$Kenyan History$q$, $q$In which year was Kenya's current Constitution promulgated?$q$, $q$2002$q$, $q$2010$q$, $q$2008$q$, $q$2013$q$, 'b', 'medium', $q$It was promulgated on 27 August 2010 after a referendum.$q$),
  ($q$Kenyan History$q$, $q$During the building of the Uganda Railway in 1898, which animals terrorised workers at Tsavo?$q$, $q$Crocodiles$q$, $q$Leopards$q$, $q$Hyenas$q$, $q$Lions$q$, 'd', 'hard', $q$The "Tsavo man-eaters" are now displayed in a museum in Chicago.$q$),
  ($q$Kenyan Wildlife & Culture$q$, $q$What is special about Nairobi National Park?$q$, $q$It lies next to a capital city$q$, $q$It is underwater$q$, $q$It is the largest in Africa$q$, $q$It has no animals$q$, 'a', 'medium', $q$Established in 1946, it was Kenya's first national park.$q$),
  ($q$Kenyan Wildlife & Culture$q$, $q$Which Kenyan national park is famous for elephants and views of Mount Kilimanjaro?$q$, $q$Aberdare$q$, $q$Amboseli$q$, $q$Meru$q$, $q$Tsavo West$q$, 'b', 'easy', $q$Kilimanjaro is across the border in Tanzania.$q$),
  ($q$Kenyan Wildlife & Culture$q$, $q$Where can you find the last two northern white rhinos in the world?$q$, $q$Nairobi National Park$q$, $q$Lake Nakuru National Park$q$, $q$Maasai Mara$q$, $q$Ol Pejeta Conservancy$q$, 'd', 'hard', $q$Najin and Fatu live under armed protection. Sudan, the last male, died in 2018.$q$),
  ($q$Kenyan Wildlife & Culture$q$, $q$Hell's Gate National Park is unusual because visitors can...$q$, $q$Camp on the lake$q$, $q$Cycle and walk among wildlife$q$, $q$Fish for crocodiles$q$, $q$Swim with hippos$q$, 'b', 'medium', $q$Its gorges and rock towers inspired scenes in films and are popular with cyclists.$q$),
