  ($q$Kenyan Geography$q$, $q$Lake Turkana is nicknamed...$q$, $q$The Rift Mirror$q$, $q$The Blue Eye$q$, $q$The Jade Sea$q$, $q$The Salt Heart$q$, 'c', 'medium', $q$It is the world's largest permanent desert lake.$q$),
  ($q$Kenyan Geography$q$, $q$Fort Jesus in Mombasa was built by which people in the 1590s?$q$, $q$The British$q$, $q$The Omanis$q$, $q$The Germans$q$, $q$The Portuguese$q$, 'd', 'hard', $q$Construction began in 1593. It became a UNESCO World Heritage Site in 2011.$q$),
  ($q$Music & Entertainment$q$, $q$Which Kenyan-raised actress won an Oscar for "12 Years a Slave"?$q$, $q$Kate Henshaw$q$, $q$Ngozi Okoro$q$, $q$Sarah Hassan$q$, $q$Lupita Nyong'o$q$, 'd', 'medium', $q$She won Best Supporting Actress at the ceremony in March 2014.$q$),
  ($q$Music & Entertainment$q$, $q$Which of these is a Kenyan afro-pop group?$q$, $q$Sauti Sol$q$, $q$Diamond Platnumz$q$, $q$Burna Boy$q$, $q$Ladysmith Black Mambazo$q$, 'a', 'easy', $q$"Sauti" is Swahili for voice or sound.$q$),
  ($q$Music & Entertainment$q$, $q$The Kenyan national anthem begins with the words...$q$, $q$Jambo Kenya$q$, $q$Tuinuke pamoja$q$, $q$Harambee Kenya$q$, $q$Ee Mungu nguvu yetu$q$, 'd', 'easy', $q$The anthem is sung in Swahili and has been used since independence in 1963.$q$),
  ($q$Music & Entertainment$q$, $q$Benga music is most strongly associated with which region?$q$, $q$The Aberdares$q$, $q$The Coast$q$, $q$North Eastern Kenya$q$, $q$Western Kenya$q$, 'd', 'hard', $q$Benga grew out of Luo guitar and dance styles and spread across Kenya.$q$)
) as v(cat, question_text, a, b, c, d, correct, difficulty, fact)
